parameters.jsCode:
const rows = $input.all().map(i => i.json);
const atRisk = [];
let checked = 0;
for (const r of rows) {
  const stock = Number(r['Stock On Hand']);
  const demand = Number(r['Weekly Demand']);
  const lead = Number(r['Lead Time Days']);
  const safety = Number(r['Safety Stock Days'] || 0);
  if (!r['SKU'] || !(demand > 0) || Number.isNaN(stock) || Number.isNaN(lead)) continue;
  checked++;
  const coverDays = (stock / demand) * 7;
  const needDays = lead + safety;
  const supplierRisk = String(r['Supplier Risk'] || 'Low');
  if (coverDays < needDays || supplierRisk === 'High') {
    atRisk.push({
      sku: r['SKU'], item: r['Item'], supplier: r['Supplier'], supplier_risk: supplierRisk,
      cover_days: Math.round(coverDays * 10) / 10, needed_days: needDays,
      gap_days: Math.round((coverDays - needDays) * 10) / 10
    });
  }
}
atRisk.sort((a, b) => a.gap_days - b.gap_days);
return [{ json: {
  generated_on: new Date().toISOString().slice(0, 10),
  skus_checked: checked,
  at_risk_count: atRisk.length,
  at_risk: atRisk.slice(0, 15)
} }];

